"use strict";

const fs = require("fs");
const path = require("path");

function double(value) {
  return value * 2;
}

module.exports = function runTypeScriptSourceProbe(input) {
  const sourcePath = path.relative(process.cwd(), path.join(__dirname, "src", "index.cts"));
  const source = fs.readFileSync(sourcePath, "utf8");
  const normalized = input.label.trim().toLowerCase();
  const doubled = double(input.count);
  return {
    ok: normalized === "autojs" && doubled === 12 && source.includes("type ProbeInput"),
    summary: "ts:source/" + normalized + "/" + input.count + "/" + doubled,
  };
};
